```python
"""Run-length encoding and decoding for letter strings."""


def encode(s):
    """Return the run-length encoding of s.

    Each run of the same character becomes its run length followed by the
    character, and case matters. For example, encode("aaabcc") returns
    "3a1b2c". encode("") returns "".

    Raises ValueError if s contains a digit, because the encoding could not
    be decoded unambiguously.
    """
    for char in s:
        if char.isdigit():
            raise ValueError(f"cannot encode a string containing digit {char!r}")

    if s == "":
        return ""

    encoded_parts = []
    run_char = s[0]
    run_length = 0

    for char in s:
        if char == run_char:
            run_length += 1
        else:
            encoded_parts.append(str(run_length) + run_char)
            run_char = char
            run_length = 1

    # The final run has no following character to trigger its append.
    encoded_parts.append(str(run_length) + run_char)

    return "".join(encoded_parts)


def decode(s):
    """Return the string that the run-length encoding s represents.

    Counts may have more than one digit, so decode("12q") returns twelve
    q's. decode("") returns "".

    Raises ValueError if s is malformed: a letter with no count before it,
    a count with no letter after it, or a character that is neither a digit
    nor a letter.
    """
    decoded_parts = []
    count_digits = ""

    for char in s:
        if char.isdigit():
            count_digits += char
        elif char.isalpha():
            if count_digits == "":
                raise ValueError(f"letter {char!r} has no count before it")
            decoded_parts.append(char * int(count_digits))
            count_digits = ""
        else:
            raise ValueError(f"unexpected character {char!r}")

    if count_digits != "":
        raise ValueError("encoding ends in a count with no character after it")

    return "".join(decoded_parts)
```

